async function t(n){const s=await fetch(`${n}`);if(!s.ok)throw new Error(`API error: ${s.status}`);const o=await s.json();if(o.code!==0)throw new Error(o.message);return o.data}async function e(n=12){return t(`/api/photos/latest?count=${n}`)}async function r(){return t("/api/albums")}async function a(){return t("/api/moments")}async function c(){return t("/api/hero")}export{e as a,r as b,a as c,c as f};
